uniform float amzp_enShift;
uniform float amzp_shI;
uniform float amzp_shPeak;
uniform float amzp_shMin;
uniform float amzp_shRand;
uniform float amzp_lineDup;
uniform float amzp_shAmt;
uniform float amzp_density;
uniform float amzp_runLen;
uniform float amzp_skew;
uniform float amzp_jitter;
uniform float amzp_lineDrop;
uniform float amzp_dropDen;
uniform float amzp_shSeed;
uniform float amzp_shIntvSeed;
uniform float amzp_enShake;
uniform float amzp_skI;
uniform float amzp_skPeak;
uniform float amzp_skMin;
uniform float amzp_skRand;
uniform float amzp_skAmt;
uniform float amzp_skX;
uniform float amzp_skY;
uniform float amzp_rgbSplit;
uniform float amzp_skSkew;
uniform float amzp_skRot;
uniform float amzp_skSeed;
uniform float amzp_skIntvSeed;
uniform float amzp_enFlicker;
uniform float amzp_flI;
uniform float amzp_flPeak;
uniform float amzp_flMin;
uniform float amzp_flRand;
uniform float amzp_bright;
uniform float amzp_brightRand;
uniform float amzp_brightOff;
uniform float amzp_sat;
uniform float amzp_satRand;
uniform float amzp_satOff;
