uniform float amzp_autop;
uniform float amzp_autoSpeed;
uniform float amzp_overdrawOn;
    float2 advRot(float2 q, float a) { float cs = cos(a), sn = sin(a); return float2(cs * q.x - sn * q.y, sn * q.x + cs * q.y); }
    float prog(float p) { return (amzp_autop>0.5) ? p + time * (amzp_autoSpeed * 0.5) : p; }
    float2 l2s(float2 v) { return (float4(v, 0.0, 1.0) * amzLayerToScreen()).xy; }
    float hh(float a, float b, float c) {
        return fract(sin(mod(a, 1291.0) * 12.9898 + mod(b, 1171.0) * 78.233 + mod(c, 997.0) * 37.719 + 0.731) * 43758.5453);
    }
    float FR;
    float BURST_K;
    float burst(float sd, out float k) {
        k = 0.0;
        if (int(amzp_glitchMode) == 1) return clamp(prog(amzp_completion), 0.0, 1.0);
        float I = max(amzp_interval, 1.0);
        float off = (amzp_startZero>0.5) ? 0.0 : hh(sd, 3.1, 0.0) * I;
        float k0 = floor((FR - off) / I);
        float ph = -1.0;
        for (int j = -1; j <= 1; j++) {
            float kk = k0 + float(j);
            if ((amzp_startZero>0.5) && kk < 0.0) continue;
            float s = off + kk * I;
            if (!((amzp_startZero>0.5) && kk == 0.0)) s += (hh(kk, sd, 1.7) - 0.5) * I * clamp(amzp_intvRand, 0.0, 100.0) / 100.0;
            float r = hh(kk, sd, 2.9), dr = clamp(amzp_durRand, 0.0, 100.0) / 100.0, df;
            if (int(amzp_durMode) == 1) df = 1.0 + r * dr;
            else if (int(amzp_durMode) == 2) df = 1.0 - r * dr;
            else df = 1.0 + (r - 0.5) * 2.0 * dr;
            float L = max(I * clamp(amzp_duration, 1.0, 100.0) / 100.0 * df, 1.0);
            if (FR >= s && FR < s + L) { ph = (FR - s + 0.5) / L; k = kk; }
        }
        return ph;
    }
    float group(bool en, float gI, float pk, float mn, float rnd, float seed, float iseed) {
        if (!en) return 0.0;
        float k;
        float ph = burst(amzp_intvSeed * 1.37 + iseed * 7.13, k);
        if (ph < 0.0) return 0.0;
        float p = clamp(pk / 100.0, 0.01, 0.99);
        float tri = ph < p ? ph / p : (1.0 - ph) / (1.0 - p);
        tri = clamp(tri, 0.0, 1.0);
        tri = tri * tri * (3.0 - 2.0 * tri);
        float env = mix(clamp(mn / 100.0, 0.0, 1.0), 1.0, tri);
        if (int(amzp_glitchMode) == 1) env *= smoothstep(0.0, 0.08, ph) * smoothstep(1.0, 0.92, ph);
        float ev = 1.0;
        if (amzp_intRand > 0.0) {
            ev = 1.0 - clamp(amzp_intRand, 0.0, 100.0) / 100.0 * hh(k, amzp_intSeed, 5.3);
            if (ev * 100.0 < amzp_trigTh) return 0.0;
        }
        float gr = 1.0 - clamp(rnd, 0.0, 100.0) / 100.0 * hh(k + FR * 0.37, seed, 8.1);
        BURST_K = k;
        return max(amzp_glitchI, 0.0) / 50.0 * max(gI, 0.0) / 100.0 * env * ev * gr;
    }
    float2 edgeUV(float2 uv, out float inside) {
        inside = 1.0;
        if ((amzp_overdrawOn>0.5)) {
            if (uv.x < 0.0 || uv.y < 0.0 || uv.x > 1.0 || uv.y > 1.0) inside = 0.0;
            return clamp(uv, 0.0, 1.0);
        }
        if (int(amzp_edge) == 1) return fract(uv);
        if (int(amzp_edge) == 2) return clamp(uv, 0.0, 1.0);
        if (int(amzp_edge) == 3) {
            if (uv.x < 0.0 || uv.y < 0.0 || uv.x > 1.0 || uv.y > 1.0) inside = 0.0;
            return clamp(uv, 0.0, 1.0);
        }
        return 1.0 - abs(1.0 - mod(uv, 2.0));
    }
    float4 sampleClip(float2 px, float wB) {
        float ins;
        float2 uv = edgeUV(px / layer, ins);
        float2 s = l2s(uv);
        float4 a = amzTexture(0, s);
        if (wB > 0.0) a = mix(a, amzTexture(1, s), wB);
        return a * ins;
    }
    float3 unp(float4 c) { return c.a > 0.0001 ? c.rgb / c.a : float3(0.0); }
    float luma(float3 c) { return dot(c, float3(0.299, 0.587, 0.114)); }
    void nmFxMain() {
        float2 W = layer;
        float2 p = amzLayerNorm() * W;
        float px = screen.zw.x / max(screen.zw.x, 1.0);
        float sc = max(amzp_advScale, 0.01) * px;
        float ang = radians(amzp_advAngle);
        FR = floor(time * max(amzp_fps, 1.0) + 0.001);
        BURST_K = 0.0;
        float kB = 0.0;
        float BD = group((amzp_enBlock>0.5), amzp_bdI, amzp_bdPeak, amzp_bdMin, amzp_bdRand, amzp_bdSeed, amzp_bdIntvSeed); kB = BURST_K;
        float SH = group((amzp_enShift>0.5), amzp_shI, amzp_shPeak, amzp_shMin, amzp_shRand, amzp_shSeed, amzp_shIntvSeed);
        float SK = group((amzp_enShake>0.5), amzp_skI, amzp_skPeak, amzp_skMin, amzp_skRand, amzp_skSeed, amzp_skIntvSeed);
        float FL = group((amzp_enFlicker>0.5), amzp_flI, amzp_flPeak, amzp_flMin, amzp_flRand, amzp_flSeed, amzp_flIntvSeed);
        float wB = 0.0;
        bool trans = int(amzp_glitchMode) == 1;
        float t = clamp(prog(amzp_completion), 0.0, 1.0);
        if (trans) wB = int(amzp_style) == 1 ? smoothstep(0.3, 0.7, t) : (t >= 0.5 ? 1.0 : 0.0);
        float2 q = p;
        float Fq = FR;
        float2 shk = float2(0.0);
        if (SK > 0.0) {
            float2 r = float2(hh(Fq, amzp_skSeed, 11.0), hh(Fq, amzp_skSeed, 12.0)) * 2.0 - 1.0;
            shk = float2(amzp_skX, amzp_skY) / 100.0 * amzp_skAmt * sc * SK * SK * r;
            q -= shk;
            float rot = radians(amzp_skRot) * SK * (hh(Fq, amzp_skSeed, 13.0) * 2.0 - 1.0);
            if (rot != 0.0) q = advRot(q - W * 0.5, rot) + W * 0.5;
            q.x += amzp_skSkew / 100.0 * SK * (q.y - W.y * 0.5) * (hh(Fq, amzp_skSeed, 14.0) * 2.0 - 1.0);
        }
        float2 g = advRot(p - W * 0.5, ang);
        bool dropLine = false;
        float bandOther = 0.0;
        if (SH > 0.0) {
            float bh = max(2.0, 4.0 + clamp(amzp_runLen, 0.0, 100.0) * 1.4) * sc;
            float ph0 = hh(Fq, amzp_shSeed, 21.0) * bh;
            float bid = floor((g.y + ph0) / bh);
            float yin = fract((g.y + ph0) / bh);
            float pAct = clamp(amzp_density, 0.0, 100.0) / 100.0 * clamp(SH * 2.5, 0.0, 1.0);
            float d = 0.0;
            if (hh(bid, Fq, 22.0 + amzp_shSeed) < pAct) {
                float r = hh(bid, Fq, 23.0 + amzp_shSeed) * 2.0 - 1.0;
                d = r * abs(r) * amzp_shAmt * sc * SH * 0.6;
                d += sign(r) * amzp_skew / 100.0 * (yin - 0.5) * bh * 2.0 * clamp(SH * 2.0, 0.0, 1.0);
                bandOther = step(0.5, hh(bid, Fq, 24.0));
                float ln = floor(g.y / (6.0 * sc));
                if (hh(ln, Fq, 25.0) < clamp(amzp_lineDup, 0.0, 100.0) / 100.0 * 0.35 * clamp(SH * 2.0, 0.0, 1.0)) {
                    float x0 = (hh(ln, Fq, 26.0) - 0.5) * W.x;
                    float2 gq = advRot(q - W * 0.5, ang);
                    gq.x = x0 + (gq.x - x0) * 0.12;
                    q = advRot(gq, -ang) + W * 0.5;
                }
                if (hh(floor(g.y / (1.5 * sc)), Fq, 27.0) < clamp(amzp_lineDrop, 0.0, 100.0) / 100.0 * clamp(amzp_dropDen, 0.0, 100.0) / 100.0) dropLine = true;
            }
            float sbh = bh * 0.22;
            float sid = floor((g.y + ph0 * 0.5) / sbh);
            if (hh(sid, Fq, 28.0 + amzp_shSeed) < pAct * 0.25) d += (hh(sid, Fq, 29.0) * 2.0 - 1.0) * amzp_shAmt * 0.08 * sc * SH;
            float jl = floor(g.y / max(sc, 0.5));
            d += (hh(jl, Fq, 30.0) - 0.5) * 2.0 * clamp(amzp_jitter, 0.0, 100.0) / 100.0 * 14.0 * sc * clamp(SH * 3.0, 0.0, 1.0);
            q -= advRot(float2(d, 0.0), -ang);
        }
        float dmg = 0.0;
        float2 bq = q;
        float2 cell = float2(0.0), lc = float2(0.0);
        float kseed = (amzp_freeze>0.5) ? kB * 3.0 + 17.0 : Fq;
        if (BD > 0.0) {
            float bs = max(amzp_bdSize, 4.0) * sc;
            float2 gb = advRot(p - W * 0.5, ang) + W * 0.5;
            float row = floor(gb.y / bs);
            float L = 1.0 + floor(clamp(amzp_bdRun, 0.0, 100.0) / 100.0 * 6.0 * hh(row, kseed, 31.0 + amzp_bdSeed) + 0.5);
            float rid = floor((floor(gb.x / bs) + floor(hh(row, kseed, 32.0) * L)) / L);
            float amt = 0.05 + 0.25 * clamp(BD, 0.0, 2.0);
            if (hh(rid * 7.0 + row, kseed, 33.0 + amzp_bdSeed) < amt * 0.5) {
                dmg = 1.0;
                cell = float2(floor(gb.x / bs), row);
                lc = fract(gb / bs);
                float2 jump = floor((float2(hh(rid, row, 34.0 + kseed), hh(rid, row, 35.0 + kseed)) - 0.5) * 8.0);
                float2 src = (cell + jump + (floor(lc * 8.0) + 0.5) / 8.0) * bs;
                bq = advRot(src - W * 0.5, -ang) + W * 0.5;
            }
        }
        float wHere = wB;
        if (trans) {
            if (bandOther > 0.5) wHere = 1.0 - wHere;
            if (dmg > 0.5 && hh(cell.x, cell.y, 36.0) > 0.5) wHere = 1.0 - wHere;
        }
        float2 sp = dmg > 0.5 ? bq : q;
        float2 so = shk * clamp(amzp_rgbSplit, 0.0, 100.0) / 100.0 + float2(clamp(amzp_rgbSplit, 0.0, 100.0) / 100.0 * 10.0 * sc * clamp(SK * SK * 3.0, 0.0, 1.0), 0.0);
        float4 c0 = sampleClip(sp, wHere);
        float4 c2 = SK > 0.0 ? sampleClip(sp + so, wHere) : c0;
        float a = max(c0.a, c2.a);
        float3 u0 = unp(c0), u2 = unp(c2);
        float3 u = float3(u0.r, u0.g, u2.b);
        if (dmg > 0.5) {
            float3 orig = unp(sampleClip(q, wHere));
            float3 b = u;
            b = mix(float3(luma(b)), b, max(amzp_bdSat, 0.0) / 100.0);
            b = floor(b * 12.0 + 0.5) / 12.0;
            if (hh(cell.x, cell.y, 37.0 + kseed) < clamp(amzp_patAmt, 0.0, 100.0) / 100.0) {
                float cx = 1.0 + floor(hh(cell.x, cell.y, 38.0) * (1.0 + clamp(amzp_patCx, 0.0, 100.0) / 100.0 * 7.0));
                float cy = 1.0 + floor(hh(cell.y, cell.x, 39.0) * (1.0 + clamp(amzp_patCx, 0.0, 100.0) / 100.0 * 7.0));
                float pat = cos(3.14159 * cx * lc.x) * cos(3.14159 * cy * lc.y);
                float3 hue = clamp(abs(fract(hh(cell.x, cell.y, 40.0) + float3(1.0, 2.0 / 3.0, 1.0 / 3.0)) * 6.0 - 3.0) - 1.0, 0.0, 1.0);
                float3 pc = mix(float3(1.0), hue, clamp(amzp_patVarCol, 0.0, 100.0) / 100.0);
                float op = clamp(amzp_patOp, 0.0, 100.0) / 100.0 * (1.0 + (hh(cell.x, cell.y, 41.0) - 0.5) * 2.0 * clamp(amzp_patVarOp, 0.0, 100.0) / 100.0);
                b += pc * pat * clamp(op, 0.0, 1.0) * 0.6;
            }
            b = clamp(b, 0.0, 1.0);
            if (int(amzp_bdBlend) == 1) b = orig + b;
            else if (int(amzp_bdBlend) == 2) b = 1.0 - (1.0 - orig) * (1.0 - b);
            else if (int(amzp_bdBlend) == 3) b = orig * b;
            else if (int(amzp_bdBlend) == 4) b = abs(orig - b);
            u = b;
        }
        if (dropLine) u = float3(0.0);
        if (FL > 0.0) {
            float rb = hh(Fq, amzp_flSeed, 51.0) * 2.0 - 1.0;
            float ob = clamp(amzp_brightOff, -100.0, 100.0) / 100.0;
            float vb = clamp(ob + (1.0 - abs(ob)) * rb + (hh(Fq, amzp_flSeed, 52.0) * 2.0 - 1.0) * clamp(amzp_brightRand, 0.0, 100.0) / 100.0, -1.0, 1.0);
            vb *= max(amzp_bright, 0.0) / 100.0 * pow(clamp(FL, 0.0, 4.0), 3.0);
            u = vb >= 0.0 ? u * (1.0 + vb * 0.75) + vb * 0.08 : u * (1.0 + vb * 0.7);
            float rs = hh(Fq, amzp_flSeed, 53.0) * 2.0 - 1.0;
            float os = clamp(amzp_satOff, -100.0, 100.0) / 100.0;
            float vs = clamp(os + (1.0 - abs(os)) * rs + (hh(Fq, amzp_flSeed, 54.0) * 2.0 - 1.0) * clamp(amzp_satRand, 0.0, 100.0) / 100.0, -1.0, 1.0);
            vs *= max(amzp_sat, 0.0) / 100.0 * pow(clamp(FL, 0.0, 4.0), 1.5);
            u = mix(float3(luma(u)), u, max(1.0 + vs * 1.5, 0.0));
        }
        u = clamp(u, 0.0, 1.0);
        amzOutput = float4(u * a, a);
    }
    void amzRender() {
        nmFxMain();
        if (!(amzp_overdrawOn>0.5)) amzOutput *= amzTexture(0, amzScreenNorm()).a;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
